<?php
/** Proof — the worker (spec "Proof" 6): the pass locked against a second, --only, the report logged once, housekeeping, stale claims with their dedupe, the hourly AI poll, dispatch (Ask the Bookkeeper) and its retries. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $owner = as_member(1);
ensure_year($owner); ar_fixture();
echo "1. The pass\n";
$since = last_activity_id();
$r = worker(['--only=housekeeping,send']);
ok($r['ran'] === ['send', 'housekeeping'] && array_keys($r['results']) === ['send', 'housekeeping'] && $r['errors'] === [], '--only runs just the named steps, in the worker\'s order');
$rows = activity('worker.pass', $since);
$a = json_decode((string) ($rows[0]['after'] ?? '{}'), true);
ok(count($rows) === 1 && $rows[0]['source'] === 'cron' && $rows[0]['actor_member_id'] === null && ($a['ran'] ?? []) === ['send', 'housekeeping'] && isset($a['seconds']), 'the report is logged once as worker.pass (source cron)');
$out = (string) shell_exec('php ' . escapeshellarg(dirname(__DIR__, 3) . '/bin/worker.php') . ' --only=nonsense 2>&1; echo "exit=$?"');
ok(str_contains($out, 'Unknown step: nonsense') && str_contains($out, 'exit=2'), 'an unknown step is refused with the list of steps (exit 2)');
$lock = new PDO(sprintf('pgsql:host=%s;port=%s;dbname=%s', need('DB_HOST'), need('DB_PORT'), need('DB_NAME')), need('DB_USER'), need('DB_PASSWORD'), [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$lock->query("SELECT pg_advisory_lock(hashtext('gl_worker'))");
$since = last_activity_id();
$r = worker(['--only=send']);
ok(isset($r['skipped']) && str_contains($r['skipped'], 'another pass') && count(activity('worker.pass', $since)) === 0, 'a second pass while one holds the lock does nothing and says so (and logs nothing)');
$lock->query("SELECT pg_advisory_unlock(hashtext('gl_worker'))");
$r = worker(['--only=send']);
ok(!isset($r['skipped']), 'and runs again once the lock is free');
echo "2. Housekeeping\n";
q("INSERT INTO sso_nonces (nonce, member_id, expires_at) VALUES ('SMOKE-old', 27, now() - interval '1 hour'), ('SMOKE-live', 27, now() + interval '1 hour')");
q("INSERT INTO member_sessions (session_hash, member_id, ended_at, ended_by) VALUES ('SMOKE-ended-old', 27, now() - interval '31 days', 'member'), ('SMOKE-ended-new', 27, now() - interval '2 days', 'member')");
q("INSERT INTO notification_outbox (channel, member_id, kind, subject, body, status, sent_at) VALUES ('email', 27, 'morning_note', 'SMOKE old', 'b', 'sent', now() - interval '91 days'), ('email', 27, 'morning_note', 'SMOKE new', 'b', 'sent', now() - interval '5 days')");
$r = worker(['--only=housekeeping']);
ok((int) one("SELECT count(*) FROM sso_nonces WHERE nonce = 'SMOKE-old'") === 0 && (int) one("SELECT count(*) FROM sso_nonces WHERE nonce = 'SMOKE-live'") === 1, 'an expired sign-on nonce is deleted, a live one kept');
ok((int) one("SELECT count(*) FROM member_sessions WHERE session_hash = 'SMOKE-ended-old'") === 0 && (int) one("SELECT count(*) FROM member_sessions WHERE session_hash = 'SMOKE-ended-new'") === 1, 'a session ended over 30 days ago is deleted, a recent one kept');
ok((int) one("SELECT count(*) FROM notification_outbox WHERE subject = 'SMOKE old'") === 0 && (int) one("SELECT count(*) FROM notification_outbox WHERE subject = 'SMOKE new'") === 1, 'a sent mail row over 90 days old is deleted, a recent one kept');
ok(($r['results']['housekeeping']['sso_nonces'] ?? 0) >= 1, 'the report counts what was removed (' . json_encode($r['results']['housekeeping'] ?? []) . ')');
echo "3. Stale claims, once a day\n";
$cust = mk_customer('SMOKE Claimant'); $inv = mk_invoice($cust, [['Work', '1', '80.00']]); issue($inv);
$claim = (int) one("INSERT INTO receipt_claims (invoice_id, claimed_on, method, amount, ip_address, created_at) VALUES (:i, current_date, 'cash', 80, '127.0.0.1', now() - interval '4 days') RETURNING id", ['i' => $inv]);
$fresh = (int) one("INSERT INTO receipt_claims (invoice_id, claimed_on, method, amount, ip_address) VALUES (:i, current_date, 'cash', 5, '127.0.0.1') RETURNING id", ['i' => $inv]);
$r = worker(['--only=claims']);
$told = (int) one("SELECT count(*) FROM notifications WHERE kind = 'claim_submitted' AND record_id = :i AND title LIKE '%still waiting%'", ['i' => $inv]);
ok(($r['results']['claims']['told'] ?? 0) >= 1 && $told === (int) $r['results']['claims']['told'], 'a claim untouched for 4 days tells the holders of ar.write again; the fresh claim does not (told ' . $told . ')');
ok((int) one("SELECT count(*) FROM notifications WHERE member_id = 27 AND kind = 'claim_submitted' AND title LIKE '%still waiting%'") === 1, 'the Bookkeeper has it in the bell');
$r = worker(['--only=claims']);
ok(($r['results']['claims']['told'] ?? -1) === 0, 'the same day again: nobody is told twice (dedupe)');
$r = worker(['--only=claims'], date('Y-m-d H:i:s', strtotime('+1 day')));
ok(($r['results']['claims']['told'] ?? 0) >= 1, 'the next day: told again');
q('UPDATE receipt_claims SET status = \'dismissed\' WHERE id = :c', ['c' => $claim]);
$r = worker(['--only=claims'], date('Y-m-d H:i:s', strtotime('+2 days')));
ok(($r['results']['claims']['told'] ?? -1) === 0, 'a decided claim is left alone');
echo "4. The hourly AI poll\n";
ensure_year($owner);
$doc = ai_doc('2026-04', 'closed', [ai_line('openai', 'gpt-5', 'IT', 'Sysadmin', 5, 0, '0.5000')]);
ledger_state(['2026-04' => $doc]);
pdo()->exec('UPDATE gl_settings SET ai_statement_poll = true');
$r = worker(['--only=ai']);
ok(($r['results']['ai']['pulled'] ?? 0) === 1, 'the first pass pulls the OS\'s months');
$r = worker(['--only=ai']);
ok(isset($r['results']['ai']['skipped']) && str_contains($r['results']['ai']['skipped'], 'within the hour'), 'a second pass within the hour leaves the OS alone');
$r = worker(['--only=ai'], date('Y-m-d H:i:s', strtotime('+2 hours')));
ok(($r['results']['ai']['pulled'] ?? 0) === 1, 'two hours later it polls again');
pdo()->exec('UPDATE gl_settings SET ai_statement_poll = false');
$r = worker(['--only=ai'], date('Y-m-d H:i:s', strtotime('+4 hours')));
ok(isset($r['results']['ai']['skipped']) && str_contains($r['results']['ai']['skipped'], 'off'), 'with the setting off it does not poll');
echo "5. Handing a bill to the Bookkeeper, and the retries\n";
$vend = mk_vendor('SMOKE Dispatch Vendor'); $bill = mk_bill($vend, [['Thing', '1', '9.00']]);
kernel_state(function (array $st) { unset($st['chat_status']); $st['chat'] = ['run_id' => 77, 'status' => 'succeeded', 'finished' => true, 'reply' => str_repeat('Drafted the bill from the attachment. ', 12), 'actions' => []]; return $st; });
$since = last_activity_id();
[$c, $b] = act($bea, '/bills/ask-bookkeeper.php', ['bill' => $bill]);
$d = q("SELECT * FROM agent_dispatches WHERE record_type = 'bill' AND record_id = :b ORDER BY id DESC LIMIT 1", ['b' => $bill])[0] ?? [];
ok($c === 200 && ($d['status'] ?? '') === 'answered' && (int) $d['agent_member_id'] === 40 && (int) $d['acting_member_id'] === 27 && $d['via'] === 'chat' && (int) $d['run_id'] === 77, 'Ask the Bookkeeper: one chat turn, recorded answered, agent 40, acting Bea, the run id kept');
ok(mb_strlen((string) $d['reply_excerpt']) <= 200, 'the reply is kept to 200 characters');
$chat = array_values(array_filter(array_map('json_decode', file((string) getenv('FAKE_KERNEL_STATE') . '.chat', FILE_IGNORE_NEW_LINES) ?: [], array_fill(0, count(file((string) getenv('FAKE_KERNEL_STATE') . '.chat') ?: []), true))));
$last = end($chat);
ok(($last['agent'] ?? '') === '40' && ($last['acting'] ?? '') === '27', 'the kernel was asked for agent 40 with X-Acting-Member 27');
$lg = activity('agent.dispatch', $since);
ok(count($lg) === 1 && !str_contains((string) $lg[0]['after'], 'Drafted the bill') && json_decode((string) $lg[0]['after'], true)['status'] === 'answered', 'logged agent.dispatch with the status, never the reply');
kernel_state(function (array $st) { $st['chat_status'] = 500; return $st; });
[$c, $b] = act($bea, '/bills/ask-bookkeeper.php', ['bill' => $bill]);
$d2 = q("SELECT * FROM agent_dispatches WHERE record_id = :b ORDER BY id DESC LIMIT 1", ['b' => $bill])[0];
ok($c === 422 && $d2['status'] === 'failed' && (int) $d2['attempts'] === 1 && str_contains(msg($b), 'HTTP 500'), 'the kernel failing: 422 in words, the row failed with one attempt');
$r = worker(['--only=dispatch']);
$d2n = q('SELECT * FROM agent_dispatches WHERE id = :i', ['i' => $d2['id']])[0];
ok(($r['results']['dispatch']['retried'] ?? 0) === 1 && $d2n['status'] === 'failed' && (int) $d2n['attempts'] === 2, 'the worker retries it: still failing, two attempts');
kernel_state(function (array $st) { unset($st['chat_status']); return $st; });
$r = worker(['--only=dispatch']);
$d2n = q('SELECT * FROM agent_dispatches WHERE id = :i', ['i' => $d2['id']])[0];
ok($d2n['status'] === 'answered' && (int) $d2n['attempts'] === 3, 'the kernel back: the third attempt answers it');
kernel_state(function (array $st) { $st['chat_status'] = 500; return $st; });
act($bea, '/bills/ask-bookkeeper.php', ['bill' => $bill]);
worker(['--only=dispatch']); worker(['--only=dispatch']); $r = worker(['--only=dispatch']);
$d3 = q("SELECT * FROM agent_dispatches WHERE record_id = :b ORDER BY id DESC LIMIT 1", ['b' => $bill])[0];
ok($d3['status'] === 'failed' && (int) $d3['attempts'] === 3 && ($r['results']['dispatch']['retried'] ?? -1) === 0, 'three attempts and it stops: failed, never retried again');
kernel_state(function (array $st) { $st['chat_status'] = 403; return $st; });
[$c, $b] = act($bea, '/bills/ask-bookkeeper.php', ['bill' => $bill]);
$d4 = q("SELECT * FROM agent_dispatches WHERE record_id = :b ORDER BY id DESC LIMIT 1", ['b' => $bill])[0];
ok($c === 422 && $d4['status'] === 'refused' && str_contains(msg($b), 'may not use the expert'), 'a kernel refusal is shown in its words and recorded refused (not retried)');
kernel_state(function (array $st) { unset($st['chat_status']); return $st; });
[$c, $b] = act(as_member(26), '/bills/ask-bookkeeper.php', ['bill' => $bill]);
ok($c === 403, 'a Viewer cannot ask');
pdo()->exec("UPDATE members SET status = 'inactive' WHERE id = 40");
[$c, $b] = act($bea, '/bills/ask-bookkeeper.php', ['bill' => $bill]);
ok($c === 422 && str_contains(msg($b), 'No Bookkeeper agent'), 'with no Bookkeeper agent here it says so');
pdo()->exec("UPDATE members SET status = 'active' WHERE id = 40");
finish();
